class Solution {
public:
    int countBalanced(int low, int high) {
        if (high < 11) return 0;
        low = std::max(low, 11);

        std::string low_str = std::to_string(low);
        std::string high_str = std::to_string(high);
        std::vector<int> low_s, high_s;
        low_s.reserve(low_str.size());
        high_s.reserve(high_str.size());
        for (char c : low_str) low_s.push_back(c - '0');
        for (char c : high_str) high_s.push_back(c - '0');

        int n = static_cast<int>(high_s.size());
        int diff_lh = n - static_cast<int>(low_s.size());

        struct Key {
            int i;
            int diff;
            bool low;
            bool high;
            bool operator==(const Key& other) const noexcept {
                return i == other.i && diff == other.diff && low == other.low && high == other.high;
            }
        };

        struct KeyHash {
            std::size_t operator()(const Key& k) const noexcept {
                std::size_t h1 = std::hash<int>()(k.i);
                std::size_t h2 = std::hash<int>()(k.diff);
                std::size_t h3 = std::hash<bool>()(k.low);
                std::size_t h4 = std::hash<bool>()(k.high);
                return h1 ^ (h2 << 1) ^ (h3 << 2) ^ (h4 << 3);
            }
        };

        std::unordered_map<Key, long long, KeyHash> memo;

        std::function<long long(int, int, bool, bool)> dfs = [&](int i, int diff, bool limit_low, bool limit_high) -> long long {
            if (i == n) {
                return diff == 0 ? 1 : 0;
            }
            Key key{ i, diff, limit_low, limit_high };
            auto it = memo.find(key);
            if (it != memo.end()) return it->second;

            int lo = 0;
            if (limit_low && i >= diff_lh) lo = low_s[i - diff_lh];
            int hi = limit_high ? high_s[i] : 9;

            long long res = 0;
            int start = lo;

            if (limit_low && i < diff_lh) {
                res += dfs(i + 1, diff, true, false);
                start = 1;
            }

            for (int d = start; d <= hi; ++d) {
                int newDiff = diff + (i % 2 ? d : -d);
                bool newLow = limit_low && d == lo;
                bool newHigh = limit_high && d == hi;
                res += dfs(i + 1, newDiff, newLow, newHigh);
            }

            memo[key] = res;
            return res;
        };

        long long result = dfs(0, 0, true, true);
        return static_cast<int>(result);
    }
};

