int bruteCountBalanced(int low, int high) {
    if (high < 11) return 0;
    low = std::max(low, 11);
    int count = 0;
    for (int x = low; x <= high; ++x) {
        int n = x;
        int diff = 0;
        bool even = true;
        while (n > 0) {
            int d = n % 10;
            if (even) diff -= d;
            else diff += d;
            even = !even;
            n /= 10;
        }
        if (diff == 0) ++count;
    }
    return count;
}

